func tl0(a *tslabs, v any) []Stmt {
	a.stepWork()
	if v == nil {
		return nil
	}
	n, _ := v.(*tnode)
	if n == nil {
		return []Stmt{} // another node (an Error), as conversion makes an empty list of it
	}
	out := astSlice(&a.tl0Chunk, len(n.kids))
	for i, c := range n.kids {
		a.stepWork()
		out[i] = tAs[Stmt](tpub(c))
	}
	return out
}

